<?php require '../includes/auth.php'; if(logged_in()){header('Location: dashboard.php');exit;} $error='';if($_SERVER['REQUEST_METHOD']==='POST'){$s=db()->prepare('SELECT * FROM usuarios WHERE email=? LIMIT 1');$s->execute([trim($_POST['email']??'')]);$u=$s->fetch();if($u&&password_verify($_POST['senha']??'',$u['senha'])){$_SESSION['user']=['id'=>$u['id'],'nome'=>$u['nome'],'nivel'=>$u['nivel']];header('Location: dashboard.php');exit;}$error='E-mail ou senha inválidos.';}?><!doctype html><html lang="pt-BR"><meta charset="utf-8"><link rel="stylesheet" href="../css/style.css"><body><section><h1>Área administrativa</h1><?php if($error):?><p><?=e($error)?></p><?php endif?><form class="contact" method="post"><input type="email" name="email" placeholder="E-mail" required><input type="password" name="senha" placeholder="Senha" required><button class="button">Entrar</button></form></section></body></html>
